attribute vec2 corner;
attribute vec4 el;
attribute vec3 tint;
varying vec2 vUv;
varying vec3 vCol;
varying float vShape;
void main() {
  vec4 c = projectionMatrix * viewMatrix * vec4(cameraPosition + uSun * 50.0, 1.0);
  vec2 sp = c.xy / max(c.w, 1e-4);
